function qs<T extends HTMLElement>(selector: string, root: ParentNode = document): T {
  const el = root.querySelector(selector)
  if (!el) throw new Error(`Missing element: ${selector}`)
  return el as T
}

function formatNumber(n: number): string {
  return new Intl.NumberFormat('en-US').format(n)
}

function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n))
}

function animateCount(el: HTMLElement, target: number, options?: { prefix?: string; suffix?: string; durationMs?: number }) {
  const prefix = options?.prefix ?? ''
  const suffix = options?.suffix ?? ''
  const durationMs = options?.durationMs ?? 1100

  const startValue = 0
  const start = performance.now()

  const tick = (now: number) => {
    const t = clamp((now - start) / durationMs, 0, 1)
    const eased = 1 - Math.pow(1 - t, 3)
    const current = Math.round(startValue + (target - startValue) * eased)
    el.textContent = `${prefix}${formatNumber(current)}${suffix}`
    if (t < 1) requestAnimationFrame(tick)
  }

  requestAnimationFrame(tick)
}

function initImpactCounters() {
  const statsSection = qs<HTMLElement>('#impact')
  const statEls = Array.from(statsSection.querySelectorAll<HTMLElement>('[data-count]'))

  const io = new IntersectionObserver(
    entries => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue
        for (const el of statEls) {
          if (el.dataset.animated === 'true') continue
          const raw = el.getAttribute('data-count')
          if (!raw) continue
          const value = Number(raw)
          if (!Number.isFinite(value)) continue
          el.dataset.animated = 'true'

          const prefix = el.getAttribute('data-prefix') ?? ''
          const suffix = el.getAttribute('data-suffix') ?? ''
          animateCount(el, value, { prefix, suffix })
        }
        io.disconnect()
        break
      }
    },
    { threshold: 0.35 },
  )

  io.observe(statsSection)
}

function initMobileMenu() {
  const toggle = qs<HTMLButtonElement>('#mobileMenuButton')
  const drawer = qs<HTMLElement>('#mobileDrawer')
  const overlay = qs<HTMLButtonElement>('#mobileOverlay')

  const open = () => {
    document.documentElement.classList.add('is-locked')
    drawer.dataset.open = 'true'
    overlay.dataset.open = 'true'
    toggle.setAttribute('aria-expanded', 'true')
    drawer.setAttribute('aria-hidden', 'false')

    const firstLink = drawer.querySelector<HTMLAnchorElement>('a')
    firstLink?.focus()
  }

  const close = () => {
    document.documentElement.classList.remove('is-locked')
    drawer.dataset.open = 'false'
    overlay.dataset.open = 'false'
    toggle.setAttribute('aria-expanded', 'false')
    drawer.setAttribute('aria-hidden', 'true')
    toggle.focus()
  }

  toggle.addEventListener('click', () => {
    const isOpen = drawer.dataset.open === 'true'
    if (isOpen) close()
    else open()
  })

  overlay.addEventListener('click', close)

  drawer.addEventListener('click', e => {
    const target = e.target as HTMLElement
    if (target.closest('a')) close()
  })

  document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return
    if (drawer.dataset.open === 'true') close()
  })
}

function initDonateModal() {
  const openers = Array.from(document.querySelectorAll<HTMLButtonElement>('[data-open-donate]'))
  const modal = qs<HTMLDialogElement>('#donateDialog')
  const closeBtn = qs<HTMLButtonElement>('#donateClose')

  const presetButtons = Array.from(modal.querySelectorAll<HTMLButtonElement>('[data-donate-preset]'))
  const customWrap = qs<HTMLElement>('#customAmountWrap', modal)
  const customInput = qs<HTMLInputElement>('#customAmount', modal)
  const selectedLabel = qs<HTMLElement>('#donationSelected', modal)

  const setSelected = (preset: DonationPreset) => {
    presetButtons.forEach(btn => {
      const match = btn.getAttribute('data-donate-preset') === String(preset.amount)
      btn.dataset.selected = match ? 'true' : 'false'
    })

    if (preset.amount === 'custom') {
      customWrap.dataset.open = 'true'
      customInput.focus()
      selectedLabel.textContent = 'Custom amount'
    } else {
      customWrap.dataset.open = 'false'
      selectedLabel.textContent = preset.label
      customInput.value = ''
    }

    modal.setAttribute('data-selected', String(preset.amount))
  }

  const defaultPreset = donationPresets[1]
  setSelected(defaultPreset)

  for (const btn of presetButtons) {
    btn.addEventListener('click', () => {
      const raw = btn.getAttribute('data-donate-preset')
      const preset = donationPresets.find(p => String(p.amount) === String(raw))
      if (preset) setSelected(preset)
    })
  }

  const open = () => {
    document.documentElement.classList.add('is-locked')
    if (typeof modal.showModal === 'function') modal.showModal()
    else modal.setAttribute('open', 'true')

    const first = modal.querySelector<HTMLButtonElement>('[data-donate-preset]')
    first?.focus()
  }

  const close = () => {
    document.documentElement.classList.remove('is-locked')
    modal.close()
  }

  openers.forEach(btn => btn.addEventListener('click', open))
  closeBtn.addEventListener('click', close)

  modal.addEventListener('click', e => {
    const target = e.target as HTMLElement
    const box = modal.querySelector('.dialog__panel')
    if (!box) return
    if (target === modal) close()
  })

  modal.addEventListener('close', () => {
    document.documentElement.classList.remove('is-locked')
  })

  const form = qs<HTMLFormElement>('#donateForm', modal)
  form.addEventListener('submit', e => {
    e.preventDefault()
    const selected = modal.getAttribute('data-selected') ?? ''

    let amountText = ''
    if (selected === 'custom') {
      const v = Number(customInput.value)
      amountText = Number.isFinite(v) && v > 0 ? `$${formatNumber(v)}` : 'Custom'
    } else {
      amountText = `$${formatNumber(Number(selected))}`
    }

    const toast = qs<HTMLElement>('#toast')
    toast.textContent = `Thank you — your ${amountText} gift is ready to process. (Demo)`
    toast.dataset.show = 'true'

    window.setTimeout(() => {
      toast.dataset.show = 'false'
    }, 2600)

    close()
  })
}

function initAccordion() {
  const root = qs<HTMLElement>('#programsAccordion')
  const items = Array.from(root.querySelectorAll<HTMLElement>('.acc-item'))

  const closeAll = () => {
    for (const item of items) item.dataset.open = 'false'
  }

  for (const item of items) {
    const btn = qs<HTMLButtonElement>('.acc-trigger', item)
    btn.addEventListener('click', () => {
      const willOpen = item.dataset.open !== 'true'
      closeAll()
      item.dataset.open = willOpen ? 'true' : 'false'
      btn.setAttribute('aria-expanded', willOpen ? 'true' : 'false')
    })
  }
}

function initNewsCarousel() {
  const track = qs<HTMLElement>('#newsTrack')
  const prev = qs<HTMLButtonElement>('#newsPrev')
  const next = qs<HTMLButtonElement>('#newsNext')
  const pager = qs<HTMLElement>('#newsPager')

  const cards = Array.from(track.querySelectorAll<HTMLElement>('.news-card'))
  let index = 0

  const maxIndex = () => Math.max(0, cards.length - 1)

  const setIndex = (nextIndex: number) => {
    index = clamp(nextIndex, 0, maxIndex())

    const card = cards[index]
    if (!card) return

    const left = card.offsetLeft
    track.scrollTo({ left, behavior: 'smooth' })

    prev.disabled = index === 0
    next.disabled = index === maxIndex()
    pager.textContent = `${index + 1} / ${cards.length}`
  }

  prev.addEventListener('click', () => setIndex(index - 1))
  next.addEventListener('click', () => setIndex(index + 1))

  // Keep controls in sync with manual scroll/drag
  let raf = 0
  const syncFromScroll = () => {
    if (raf) cancelAnimationFrame(raf)
    raf = requestAnimationFrame(() => {
      let closest = 0
      let best = Infinity
      const scrollLeft = track.scrollLeft
      for (let i = 0; i < cards.length; i++) {
        const d = Math.abs(cards[i].offsetLeft - scrollLeft)
        if (d < best) {
          best = d
          closest = i
        }
      }
      index = closest
      prev.disabled = index === 0
      next.disabled = index === maxIndex()
      pager.textContent = `${index + 1} / ${cards.length}`
    })
  }

  track.addEventListener('scroll', syncFromScroll, { passive: true })

  window.addEventListener('resize', () => setIndex(index), { passive: true })
  setIndex(0)
}

function initSmoothAnchors() {
  const links = Array.from(document.querySelectorAll<HTMLAnchorElement>('a[href^="#"]'))
  for (const link of links) {
    link.addEventListener('click', e => {
      const href = link.getAttribute('href') ?? ''
      if (!href.startsWith('#')) return
      const id = href.slice(1)
      const target = document.getElementById(id)
      if (!target) return
      e.preventDefault()
      target.scrollIntoView({ behavior: 'smooth', block: 'start' })
    })
  }
}

