function qs<T extends HTMLElement>(selector: string, root: ParentNode = document): T {
  const el = root.querySelector(selector)
  if (!el) throw new Error(`Missing element: ${selector}`)
  return el as T
}

function formatNumber(n: number): string {
  return new Intl.NumberFormat('en-US').format(n)
}

function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n))
}

function animateCount(el: HTMLElement, target: number, options?: { prefix?: string; suffix?: string; durationMs?: number }) {
  const prefix = options?.prefix ?? ''
  const suffix = options?.suffix ?? ''
  const durationMs = options?.durationMs ?? 1100

  const startValue = 0
  const start = performance.now()

  const tick = (now: number) => {
    const t = clamp((now - start) / durationMs, 0, 1)
    const eased = 1 - Math.pow(1 - t, 3)
    const current = Math.round(startValue + (target - startValue) * eased)
    el.textContent = `${prefix}${formatNumber(current)}${suffix}`
    if (t < 1) requestAnimationFrame(tick)
  }

  requestAnimationFrame(tick)
}

function initImpactCounters() {
  const statsSection = qs<HTMLElement>('#impact')
  const statEls = Array.from(statsSection.querySelectorAll<HTMLElement>('[data-count]'))

  const io = new IntersectionObserver(
    entries => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue
        for (const el of statEls) {
          if (el.dataset.animated === 'true') continue
          const raw = el.getAttribute('data-count')
          if (!raw) continue
          const value = Number(raw)
          if (!Number.isFinite(value)) continue
          el.dataset.animated = 'true'

          const prefix = el.getAttribute('data-prefix') ?? ''
          const suffix = el.getAttribute('data-suffix') ?? ''
          animateCount(el, value, { prefix, suffix })
        }
        io.disconnect()
        break
      }
    },
    { threshold: 0.35 },
  )

  io.observe(statsSection)
}

